SELECT bool_and(ROW(t.id,t.type,t.slug,t.id_level,t.points_version,t.finalized_at,t.date_created) IS NOT DISTINCT FROM ROW(o.id,o.type,o.slug,o.id_level,o.points_version,o.finalized_at,o.date_created) AND t.start_at=o.start_at+CASE WHEN $1='active' THEN interval '6 hours' ELSE interval '0' END AND t.end_at=o.end_at+CASE WHEN $1='active' THEN interval '6 hours' ELSE interval '0' END AND CASE WHEN $1='active' THEN t.date_updated IS NOT NULL ELSE t.date_updated IS NOT DISTINCT FROM o.date_updated END) AS value FROM public.track_tournament t JOIN original_tournaments o USING(id)
